  name: string;
  x: number;
  y: number;
  hint: string;
  found?: boolean;
};

export type HiddenLevel = {
  id: string;
  title: string;
  sceneAsset: string;
  intro: string;
  complete: string;
  objects: HiddenObject[];
};

export type HiddenGameConfig = {
  id: string;
  theme: string;
  style: string;
  difficulty: string;
  objectCountPerLevel: number;
  rules: { timer: boolean; failState: boolean; hintCooldownSec: number; tapFeedback: string };
  levels: HiddenLevel[];
};

export function createFantasyLibrarySession(config: HiddenGameConfig) {
  let levelIndex = 0;
  const levels = config.levels.map(l => ({ ...l, objects: l.objects.map(o => ({ ...o, found: false })) }));

  function currentLevel() {
    return levels[levelIndex];
  }

  function findObject(objectId: string) {
    const level = currentLevel();
    const obj = level.objects.find(o => o.id === objectId);
    if (!obj || obj.found) return { ok: false, message: "再仔细看看，小猫咪还在偷笑呢。" };
    obj.found = true;
    const done = level.objects.every(o => o.found);
    return { ok: true, done, message: done ? level.complete : `找到了！${obj.name}回到玩具篮啦。` };
  }

  function getHint() {
    const next = currentLevel().objects.find(o => !o.found);
    return next ? next.hint : currentLevel().complete;
  }

  function nextLevel() {
    if (!currentLevel().objects.every(o => o.found)) return false;
    if (levelIndex < levels.length - 1) { levelIndex += 1; return true; }
    return false;
  }

  return { configId: config.id, currentLevel, findObject, getHint, nextLevel };
}
